function sumUsageForNode(runData, nodeName) {
  const runs = runData?.[nodeName]; // one entry per time this node ran within the execution
  if (!Array.isArray(runs) || !runs.length) return null;
  let prompt = 0, completion = 0, total = 0, found = false;
  for (const run of runs) {
    // Chat Model sub-nodes output on the ai_languageModel connection type, not main —
    // confirmed live against a real execution's stored runData.
    const items = run?.data?.ai_languageModel?.[0] ?? run?.data?.main?.[0] ?? [];
    for (const item of items) {
      const usage = item?.json?.tokenUsageEstimate ?? item?.json?.tokenUsage ?? item?.json?.response?.llmOutput?.tokenUsage ?? null;
      if (usage) {
        found = true;
        const p = usage.promptTokens ?? usage.prompt_tokens ?? 0;
        const c = usage.completionTokens ?? usage.completion_tokens ?? 0;
        prompt += p;
        completion += c;
        total += usage.totalTokens ?? usage.total_tokens ?? (p + c);
      }
    }
  }
  return found ? { prompt_tokens: prompt, completion_tokens: completion, total_tokens: total } : null;
}

